<?php
namespace App\Services\Shopify;

use App\Modules\Shopify\Models\ShopifySkinAnalysisConfigurationModel;
use App\Modules\Shopify\Models\ShopifySkinAnalysisImageModel;
use App\Modules\Shopify\Models\ShopifySkinAnalysisLeadModel;
use App\Services\Common\R2StorageLibrary;
use Admin\Services\PatientRegistrationService;
use CodeIgniter\HTTP\Files\UploadedFile;
use InvalidArgumentException;
use RuntimeException;

final class ShopifySkinAnalysisService
{
    private const MIMES=['image/jpeg','image/png','image/webp'];
    private const ANGLES=['front','left','right','back','closeup'];
    public function __construct(private readonly ?ShopifySkinAnalysisLeadModel $leads=null, private readonly ?ShopifySkinAnalysisImageModel $images=null, private readonly ?ShopifySkinAnalysisConfigurationModel $configs=null, private readonly ?R2StorageLibrary $storage=null) {}

    public function submit(array $context,array $fields,array $files,string $key): array
    {
        $store=trim((string)($context['store_domain']??'')); $customer=trim((string)($context['customer_id']??''));
        if($store===''||$customer==='') throw new RuntimeException('SHOPIFY_PROXY_CONTEXT_MISSING');
        if(!preg_match('/^[A-Za-z0-9._:-]{8,191}$/',$key)) throw new InvalidArgumentException('A valid Idempotency-Key header is required.');
        $model=$this->leads??new ShopifySkinAnalysisLeadModel();
        $existing=$model->where(['store_domain'=>$store,'shopify_customer_id'=>$customer,'idempotency_key'=>$key])->first();
        if($existing)return $this->public($existing);
        $first=trim((string)($fields['first_name']??'')); if($first===''||mb_strlen($first)>100)throw new InvalidArgumentException('First name is required and must be at most 100 characters.');
        if(count($files)<1||count($files)>5)throw new InvalidArgumentException('Upload between 1 and 5 skin images.');
        $config=($this->configs??new ShopifySkinAnalysisConfigurationModel())->where('is_active',1)->orderBy('version','DESC')->first();
        if(!$config)throw new RuntimeException('SHOPIFY_SKIN_ANALYSIS_CONFIGURATION_MISSING');
        $q=['first_name'=>$first,'last_name'=>trim((string)($fields['last_name']??''))?:null,'age'=>($fields['age']??'')!==''?(int)$fields['age']:null,'gender'=>trim((string)($fields['gender']??''))?:null,'email'=>trim((string)($fields['email']??''))?:null,'mobile_number'=>trim((string)($fields['mobile_number']??''))?:null,'country_code'=>trim((string)($fields['country_code']??''))?:null,'date_of_birth'=>trim((string)($fields['date_of_birth']??''))?:null,'concern'=>trim((string)($fields['concern']??''))?:null,'health_list'=>trim((string)($fields['health_list']??''))?:null];
        $now=date('Y-m-d H:i:s'); $ref='SAI-'.strtoupper(bin2hex(random_bytes(6)));
        try {
            $id=$model->insert(['lead_reference'=>$ref,'store_domain'=>$store,'shopify_customer_id'=>$customer,'idempotency_key'=>$key,'first_name'=>$first,'last_name'=>$q['last_name'],'age'=>$q['age'],'gender'=>$q['gender'],'email'=>$q['email'],'mobile_number'=>$q['mobile_number'],'country_code'=>$q['country_code'],'date_of_birth'=>$q['date_of_birth'],'concern'=>$q['concern'],'health_list'=>$q['health_list'],'questionnaire_json'=>json_encode($q,JSON_UNESCAPED_SLASHES),'status'=>'processing','created_at'=>$now,'updated_at'=>$now],true);
        } catch (\Throwable $e) {
            $race=$model->where(['store_domain'=>$store,'shopify_customer_id'=>$customer,'idempotency_key'=>$key])->first();
            if ($race) return $this->public($race);
            throw new RuntimeException('SHOPIFY_SKIN_ANALYSIS_LEAD_CREATE_FAILED', 0, $e);
        }
        if(!$id)throw new RuntimeException('SHOPIFY_SKIN_ANALYSIS_LEAD_CREATE_FAILED');
        $rows=[];$keys=[];$persisted=false;
        try {
            foreach(array_values($files) as $i=>$file){$this->validate($file);$angle=$this->angle($fields,$i);$ext=strtolower((string)pathinfo($file->getName(),PATHINFO_EXTENSION));$path='shopify/skin-analysis/'.$ref.'/'.$angle.'-'.bin2hex(random_bytes(8)).'.'.($ext?:'bin');($this->storage??new R2StorageLibrary())->uploadFile($path,$file);$keys[]=$path;$rows[]=['lead_id'=>(int)$id,'angle'=>$angle,'storage_key'=>$path,'mime_type'=>(string)$file->getMimeType(),'file_size'=>(int)$file->getSize(),'created_at'=>$now];}
            (new ShopifySkinAnalysisImageModel())->insertBatch($rows);$persisted=true;
            $result=$this->analyze($config,$q,$files,$ref);$model->update((int)$id,['status'=>'completed','result_json'=>json_encode($result,JSON_UNESCAPED_SLASHES),'processed_at'=>$now,'updated_at'=>date('Y-m-d H:i:s')]);service('audit')->record('shopify.skin_analysis_completed',['lead_reference'=>$ref,'configuration_version'=>(int)$config['version']]);
        }catch(\Throwable $e){if(!$persisted)foreach($keys as $path){try{($this->storage??new R2StorageLibrary())->delete($path);}catch(\Throwable){}}$code=$e instanceof InvalidArgumentException?'VALIDATION_FAILED':$this->code($e->getMessage());$model->update((int)$id,['status'=>'failed','error_code'=>$code,'error_message'=>$code,'updated_at'=>date('Y-m-d H:i:s')]);log_message('error','Shopify skin analysis failed '.json_encode(['lead_reference'=>$ref,'error_code'=>$code,'exception_class'=>get_class($e)],JSON_UNESCAPED_SLASHES));}
        return $this->public($model->find((int)$id));
    }

    public function status(array $context,string $reference): array
    {
        $lead=($this->leads??new ShopifySkinAnalysisLeadModel())->where(['lead_reference'=>trim($reference),'store_domain'=>(string)($context['store_domain']??''),'shopify_customer_id'=>(string)($context['customer_id']??'')])->first();
        if(!$lead)throw new RuntimeException('SHOPIFY_SKIN_ANALYSIS_NOT_FOUND'); return $this->public($lead,true);
    }
    public function adminList(): array{return ($this->leads??new ShopifySkinAnalysisLeadModel())->orderBy('id','DESC')->findAll(100);}
    public function adminFind(int $id):?array{$lead=($this->leads??new ShopifySkinAnalysisLeadModel())->find($id);if(!$lead)return null;$lead['patient_reference']=!empty($lead['patient_id'])?(string)(db_connect()->table('patients')->select('registration_number')->where('id',(int)$lead['patient_id'])->get()->getRow('registration_number')??''):'';$lead['images']=($this->images??new ShopifySkinAnalysisImageModel())->where('lead_id',$id)->orderBy('id','ASC')->findAll();foreach($lead['images'] as &$image){try{$image['temporary_url']=($this->storage??new R2StorageLibrary())->getTemporaryUrl((string)$image['storage_key'],10,(string)$image['mime_type'],'inline');}catch(\Throwable){$image['temporary_url']='';}unset($image['storage_key']);}unset($image);return $lead;}
    public function linkPatient(int $id,string $reference,int $actor):array{$lead=($this->leads??new ShopifySkinAnalysisLeadModel())->find($id);if(!$lead)throw new InvalidArgumentException('Skin analysis lead was not found.');$patient=db_connect()->table('patients')->select('id,registration_number,status')->where('registration_number',trim($reference))->get()->getRowArray();if(!$patient||(int)$patient['status']!==1)throw new InvalidArgumentException('Select an active ROOTINS patient.');($this->leads??new ShopifySkinAnalysisLeadModel())->update($id,['patient_id'=>(int)$patient['id'],'updated_at'=>date('Y-m-d H:i:s')]);service('audit')->record('admin.shopify_skin_analysis_lead_patient_linked',['lead_id'=>$id,'patient_reference'=>$patient['registration_number'],'actor_user_id'=>$actor]);return ['reference'=>$lead['lead_reference'],'patient_reference'=>$patient['registration_number']];}
    public function createPatient(int $id,array $input,int $actor):array{$lead=($this->leads??new ShopifySkinAnalysisLeadModel())->find($id);if(!$lead)throw new InvalidArgumentException('Skin analysis lead was not found.');if(!empty($lead['patient_id']))return ['reference'=>$lead['lead_reference'],'patient_reference'=>(string)(db_connect()->table('patients')->select('registration_number')->where('id',(int)$lead['patient_id'])->get()->getRow('registration_number')??'')];$mobile=trim((string)($input['mobile_number']??$lead['mobile_number']??''));$country=trim((string)($input['country_code']??$lead['country_code']??''));$dob=trim((string)($input['date_of_birth']??$lead['date_of_birth']??''));if($mobile===''||$country===''||$dob==='')throw new InvalidArgumentException('Mobile number, country code, and date of birth are required.');$result=(new PatientRegistrationService())->register(['clinic_id'=>null,'first_name'=>$lead['first_name'],'last_name'=>$lead['last_name']??'','gender'=>$lead['gender'],'date_of_birth'=>$dob,'email'=>trim((string)($input['email']??$lead['email']??'')),'mobile_number'=>$mobile,'country_code'=>$country],$actor,['source_type'=>'shopify','source_user_id'=>$actor,'source_reference'=>'skin-analysis:'.$lead['lead_reference']]);($this->leads??new ShopifySkinAnalysisLeadModel())->update($id,['patient_id'=>(int)$result['id'],'mobile_number'=>$mobile,'country_code'=>$country,'date_of_birth'=>$dob,'updated_at'=>date('Y-m-d H:i:s')]);service('audit')->record('admin.shopify_skin_analysis_lead_patient_created',['lead_id'=>$id,'patient_reference'=>$result['registration_number'],'actor_user_id'=>$actor]);return ['reference'=>$lead['lead_reference'],'patient_reference'=>$result['registration_number']];}
    public function retry(int $id):array{$leadModel=$this->leads??new ShopifySkinAnalysisLeadModel();$lead=$leadModel->find($id);if(!$lead)throw new InvalidArgumentException('Skin analysis lead was not found.');$rows=($this->images??new ShopifySkinAnalysisImageModel())->where('lead_id',$id)->orderBy('id','ASC')->findAll();if($rows===[])throw new RuntimeException('SHOPIFY_SKIN_ANALYSIS_IMAGES_NOT_FOUND');$config=($this->configs??new ShopifySkinAnalysisConfigurationModel())->where('is_active',1)->orderBy('version','DESC')->first();if(!$config)throw new RuntimeException('SHOPIFY_SKIN_ANALYSIS_CONFIGURATION_MISSING');$photos=[];foreach($rows as $row){$object=($this->storage??new R2StorageLibrary())->getObject((string)$row['storage_key']);$photos[]=['angle'=>(string)$row['angle'],'mime'=>(string)$row['mime_type'],'bytes'=>(string)($object['Body']??'')];}$q=json_decode((string)($lead['questionnaire_json']??''),true);$q=is_array($q)?$q:['first_name'=>(string)$lead['first_name']];$leadModel->update($id,['status'=>'processing','error_code'=>null,'error_message'=>null,'updated_at'=>date('Y-m-d H:i:s')]);try{$result=$this->analyzePhotos($config,$q,$photos,(string)$lead['lead_reference']);$leadModel->update($id,['status'=>'completed','result_json'=>json_encode($result,JSON_UNESCAPED_SLASHES),'processed_at'=>date('Y-m-d H:i:s'),'updated_at'=>date('Y-m-d H:i:s')]);service('audit')->record('admin.shopify_skin_analysis_retried',['lead_id'=>$id,'status'=>'completed']);}catch(\Throwable $e){$code=$this->code($e->getMessage());$leadModel->update($id,['status'=>'failed','error_code'=>$code,'error_message'=>$code,'updated_at'=>date('Y-m-d H:i:s')]);throw new RuntimeException('SHOPIFY_SKIN_ANALYSIS_RETRY_FAILED',0,$e);}return $this->public($leadModel->find($id),true);}

    private function validate(UploadedFile $f):void{if(!$f->isValid()||$f->getError()!==UPLOAD_ERR_OK||$f->hasMoved()||$f->getSize()<1||$f->getSize()>10485760||!in_array(strtolower((string)$f->getMimeType()),self::MIMES,true))throw new InvalidArgumentException('Each skin image must be a valid JPG, PNG, or WebP file no larger than 10 MB.');}
    private function angle(array $fields,int $i):string{$angles=$fields['angles']??[];if(is_string($angles))$angles=array_map('trim',explode(',',$angles));$angle=is_array($angles)?strtolower(trim((string)($angles[$i]??''))):'';return in_array($angle,self::ANGLES,true)?$angle:(self::ANGLES[$i]??'front');}
    private function analyze(array $config,array $q,array $files,string $ref):array{$photos=[];foreach(array_values($files) as $i=>$f)$photos[]=['angle'=>self::ANGLES[$i]??'photo','mime'=>strtolower((string)$f->getMimeType()),'bytes'=>(string)file_get_contents($f->getTempName())];return $this->analyzePhotos($config,$q,$photos,$ref);}
    private function analyzePhotos(array $config,array $q,array $photos,string $ref):array{return $this->requestOpenAi($config,$q,$photos,$ref);}
    private function requestOpenAi(array $config,array $q,array $photos,string $ref):array{$key=trim((string)env('OPENAI_API_KEY'));if($key==='')throw new RuntimeException('OPENAI_CONFIGURATION_MISSING');$content=[['type'=>'text','text'=>'Patient context: '.json_encode($q,JSON_UNESCAPED_SLASHES)]];foreach($photos as $i=>$p){$content[]=['type'=>'text','text'=>'Photo '.($i+1).': '.$p['angle']];$content[]=['type'=>'image_url','image_url'=>['url'=>'data:'.$p['mime'].';base64,'.base64_encode($p['bytes']),'detail'=>'high']];}$schema=json_decode((string)$config['schema_json'],true);$body=['model'=>(string)$config['model'],'temperature'=>(float)$config['temperature'],'messages'=>[['role'=>'system','content'=>(string)$config['prompt_text']],['role'=>'user','content'=>$content]],'response_format'=>['type'=>'json_schema','json_schema'=>['name'=>'rootins_skin_report','strict'=>true,'schema'=>$schema]]];$h=curl_init('https://api.openai.com/v1/chat/completions');if($h===false)throw new RuntimeException('OPENAI_CURL_UNAVAILABLE');curl_setopt_array($h,[CURLOPT_POST=>true,CURLOPT_RETURNTRANSFER=>true,CURLOPT_HTTPHEADER=>['Authorization: Bearer '.$key,'Content-Type: application/json'],CURLOPT_POSTFIELDS=>json_encode($body,JSON_UNESCAPED_SLASHES),CURLOPT_TIMEOUT=>120]);$raw=curl_exec($h);$status=(int)curl_getinfo($h,CURLINFO_HTTP_CODE);$errno=curl_errno($h);curl_close($h);if(!is_string($raw)||$status<200||$status>=300){log_message('error','Shopify skin analysis OpenAI failure '.json_encode(['lead_reference'=>$ref,'configuration_version'=>(int)($config['version']??0),'stage'=>$errno?'curl_request_failed':'http_request_failed','http_status'=>$status],JSON_UNESCAPED_SLASHES));throw new RuntimeException($errno?'OPENAI_CURL_REQUEST_FAILED':'OPENAI_HTTP_REQUEST_FAILED');}$decoded=json_decode($raw,true);$result=is_string($decoded['choices'][0]['message']['content']??null)?json_decode($decoded['choices'][0]['message']['content'],true):null;if(!is_array($result))throw new RuntimeException('OPENAI_RESPONSE_INVALID');return $result;}
    private function code(string $message):string{return preg_match('/^[A-Z0-9_]{3,100}$/',$message)===1?$message:'SHOPIFY_SKIN_ANALYSIS_PROCESSING_FAILED';}
    private function public(?array $lead,bool $result=false):array{if(!$lead)return[];$out=['reference'=>(string)$lead['lead_reference'],'status'=>(string)$lead['status'],'created_at'=>$lead['created_at']??null];if($result&&(string)$lead['status']==='completed')$out['result']=json_decode((string)$lead['result_json'],true);if((string)$lead['status']==='failed')$out['error_code']=(string)($lead['error_code']??'SHOPIFY_SKIN_ANALYSIS_FAILED');return $out;}
}
